window.LESSONS = {};
// Each lesson is an authored unit, not an automatically generated roadmap card.
function lesson(w, sections, example, walkthrough, prompt, starter, hints, solution, quiz, refs, tests='') {
  window.LESSONS[w] = {sections, example, walkthrough, prompt, starter, hints, solution, quiz, refs, tests};
}
function q(prompt, options, answer, explanation) { return {prompt, options, answer, explanation}; }
const PY='https://docs.python.org/3.12/tutorial/';
const FAST='https://fastapi.tiangolo.com/tutorial/';
const PG='https://www.postgresql.org/docs/current/';
const MDN='https://developer.mozilla.org/en-US/docs/';
const OWASP='https://cheatsheetseries.owasp.org/cheatsheets/';
lesson(1,
[['從輸入與輸出開始','函式把一件工作命名。先寫出輸入的資料形狀、輸出的型別，再決定迴圈。成績平均接收一組數字，回傳一個平均值；顯示文字與讀取鍵盤留在外層，核心計算才容易測試。'],['list、dict 與空資料','list 表示有順序的一組資料，dict 以鍵查詢欄位。一位學生可以是 dict，多位學生放在 list。空清單沒有可計算的平均，本課約定回傳 None；0 是有效分數，不能用 0 代替「沒有資料」。不要把所有輸入、儲存、計算塞進同一個函式。']],
`def average(scores):\n    if not scores:\n        return None\n    return sum(scores) / len(scores)\n\nstudents = [{"id": 1, "name": "Alice", "scores": [80, 100]}]\nprint(average(students[0]["scores"]))`,
['students[0] 取得第一位學生；["scores"] 取得其成績清單。','if not scores 先處理空資料，再做除法，避免除以零。','return 把結果交回呼叫者；print 只是把結果顯示出來。範例印出 90.0。'],
'實作 average(scores)：有效分數為 0～100 的 int 或 float，但不接受 bool。空清單回傳 None，非數字與超出範圍的分數拋出 ValueError。輸入清單不得被修改。',
`def average(scores):\n    # 先處理空資料，再驗證每個分數\n    pass\n\nprint(average([80, 100]))`,
['用 for score in scores 逐一檢查；Python 的 bool 是 int 的子類別，需額外排除。','可用 isinstance(score, (int, float))；用 not 0 <= score <= 100 拒絕 NaN 與範圍錯誤。'],
`def average(scores):\n    if not scores:\n        return None\n    for score in scores:\n        if isinstance(score, bool) or not isinstance(score, (int, float)):\n            raise ValueError("分數必須是數字")\n        if not 0 <= score <= 100:\n            raise ValueError("分數必須介於 0～100")\n    return sum(scores) / len(scores)`,
[q('為什麼空清單回傳 None，而不是 0？',['避免迴圈','區分沒有資料與平均為零','None 能自動儲存檔案'],1,'零分是有效結果；None 表示此處沒有可計算的結果。'),q('return 和 print 的差異？',['return 交回結果，print 顯示文字','兩者完全一樣','print 會儲存結果'],0,'測試與其他函式可使用回傳值，不應依賴畫面上的文字。'),q('sorted(students, key=...) 的作用？',['修改學生姓名','永遠改動原清單','回傳依指定比較鍵排序的新清單'],2,'sorted 回傳新清單；list.sort 則在原清單上排序。')],
[["Python：資料結構",PY+'datastructures.html']],
`assert average([]) is None, "空資料應回傳 None"\nassert average([0, 100]) == 50\nassert average([80, 90, 100]) == 90\nassert average([0]) == 0\na = [70, 90]; average(a); assert a == [70, 90]\nfor bad in ([-1], [101], ["90"], [True], [float("nan")]):\n    try: average(bad)\n    except ValueError: pass\n    else: raise AssertionError(f"應拒絕 {bad}")`);
lesson(2,
[['資料與行為怎麼分工','class 將相關的狀態與操作組織起來。Student 可以儲存姓名與成績，add_score 統一驗證規則。只有資料傳遞時 dict 可能已足夠，class 並非必然較好。模組是 Python 檔案；import 把另一個模組的名稱帶進來。'],['例外要放在哪裡','raise 表示操作不能完成，except 由知道如何回應的外層處理。核心函式拋出 ValueError，CLI 再提示使用者重新輸入。避免 except: pass，否則問題消失在畫面上，資料卻可能已出錯。每位學生應有自己的清單，不要用共享的類別屬性 scores = []。']],
`class Student:\n    def __init__(self, name):\n        self.name = name\n        self.scores = []\n\n    def add_score(self, score):\n        if isinstance(score, bool) or not isinstance(score, (int, float)):\n            raise ValueError("分數型別錯誤")\n        if not 0 <= score <= 100:\n            raise ValueError("分數範圍錯誤")\n        self.scores.append(score)\n\nalice = Student("Alice")\nalice.add_score(85)\nprint(alice.scores)`,
['__init__ 在建立 Student 時初始化個別物件。','self.scores = [] 每次建立新的清單，學生之間不會共用成績。','先驗證再 append；錯誤輸入不應留下半套狀態。範例輸出 [85]。'],
'完成 Student(name)、add_score(score)、average()。空成績平均回傳 None；add_score 採用 Week 1 的驗證規則。建立兩位學生，確認資料互不影響。',
`class Student:\n    def __init__(self, name):\n        self.name = name\n        self.scores = []\n\n    def add_score(self, score):\n        pass\n\n    def average(self):\n        pass`,
['average() 讀取 self.scores，沒有額外的 scores 引數。','所有驗證都在 append 前完成；拒絕輸入後再檢查清單沒有變動。'],
`class Student:\n    def __init__(self, name):\n        self.name = name\n        self.scores = []\n\n    def add_score(self, score):\n        if isinstance(score, bool) or not isinstance(score, (int, float)) or not 0 <= score <= 100:\n            raise ValueError("無效分數")\n        self.scores.append(score)\n\n    def average(self):\n        return sum(self.scores) / len(self.scores) if self.scores else None`,
[q('學生的 scores 應在哪裡初始化？',['在 class 裡共用一份清單','在 __init__ 建立個別清單','在 except 裡'],1,'可變的類別屬性可能被所有物件共用；物件資料應在初始化時建立。'),q('捕捉 ValueError 後直接 pass 有何問題？',['讓錯誤消失且無法得知失敗','自動改善資料','自動重新輸入'],0,'外層應提供有意義的回應或記錄，不能把失敗當成功。'),q('哪個是合理的設計判斷？',['所有 dict 都要改成 class','每個檔案只能有一個函式','按狀態與操作需要選 dict 或 class'],2,'工程設計依問題選擇，不按語法複雜度評價。')],
[["Python：類別",PY+'classes.html'],["Python：例外",PY+'errors.html']],
`a = Student("A"); b = Student("B")\nassert a.average() is None\na.add_score(80); a.add_score(100)\nassert a.average() == 90\nassert b.scores == [], "學生不應共享清單"\nfor bad in (-1, 101, "80", True, float("nan")):\n    try: a.add_score(bad)\n    except ValueError: pass\n    else: raise AssertionError("錯誤分數未拒絕")\nassert a.scores == [80, 100], "錯誤輸入不應更動資料"`);
lesson(3,
[['JSON 儲存的是資料','記憶體清單會隨程式結束消失。json.dumps 把 Python 資料轉為字串，json.loads 再解析回資料。JSON 不儲存物件方法，日期等型別需要明確轉換。檔案不存在與檔案損毀是兩種問題；不要把損毀檔案當空清單覆寫。'],['型別提示與測試','list[int] 等提示供人與工具理解，不會自動在執行時驗證資料。pytest 用 assert 比較實際與預期結果。先選正常、空資料、邊界與錯誤案例；測試應證明需求成立，而非只確認某行程式被呼叫。金額正式專案應用整數最小單位或 Decimal 避免浮點誤差。']],
`import json\nfrom pathlib import Path\n\nrecords = [{"kind": "income", "amount": 100}]\npath = Path("records.json")\npath.write_text(json.dumps(records, ensure_ascii=False), encoding="utf-8")\nloaded = json.loads(path.read_text(encoding="utf-8"))\nassert loaded == records\nprint(loaded)`,
['write_text 明確指定 UTF-8；dumps 產生可寫入檔案的文字。','重新讀入後比較內容，而非只看檔案存在。','瀏覽器 Python 的檔案系統是暫存實驗環境；重新執行會重建環境，正式檔案儲存請在自己的電腦驗證。'],
'實作 total_expenses(records)：只加總 kind="expense" 的 amount；本題金額為非負整數（不接受 bool），每筆 kind 只能是 income 或 expense。所有記錄都要驗證，錯誤時 ValueError；空清單為 0。',
`def total_expenses(records: list[dict]) -> int:\n    pass\n\nprint(total_expenses([{ "kind": "expense", "amount": 30 }]))`,
['先驗證 kind 及 amount，再判斷是否要加進支出總額。','用 record.get(...) 取得欄位，缺欄位也應視為無效資料。'],
`def total_expenses(records: list[dict]) -> int:\n    total = 0\n    for record in records:\n        if not isinstance(record, dict):\n            raise ValueError("記錄必須是 dict")\n        kind, amount = record.get("kind"), record.get("amount")\n        if kind not in ("income", "expense") or type(amount) is not int or amount < 0:\n            raise ValueError("無效記錄")\n        if kind == "expense":\n            total += amount\n    return total`,
[q('type hint 會自動拒絕執行時錯誤輸入嗎？',['一定會','不會，仍需驗證','會修正 JSON'],1,'Python 不以一般型別提示強制檢查執行時資料。'),q('檔案解析失敗時應怎麼做？',['回報損毀並保護原檔','立即寫入空清單','當作全部資料已刪除'],0,'讀不到並不代表沒有資料；錯誤處理不能破壞待救回的檔案。'),q('有意義的平均測試應包含？',['只有平均等於 90','只測 print','正常、空資料與錯誤輸入'],2,'邊界與錯誤案例能暴露正常示範沒有涵蓋的行為。')],
[["Python：JSON",'https://docs.python.org/3.12/library/json.html'],["pytest：入門",'https://docs.pytest.org/en/stable/getting-started.html']],
`assert total_expenses([]) == 0\nassert total_expenses([{"kind":"income","amount":100},{"kind":"expense","amount":30},{"kind":"expense","amount":20}]) == 50\nfor r in ({"kind":"expense","amount":-1},{"kind":"expense","amount":True},{"kind":"expense","amount":"10"},{"kind":"other","amount":1},{"kind":"income","amount":-5},{},None):\n    try: total_expenses([r])\n    except ValueError: pass\n    else: raise AssertionError(f"應拒絕 {r}")`);
lesson(4,
[['程式成為 process','終端機裡的 shell 解析指令，作業系統建立 process，Python 解譯器載入程式。PID 是執行個體的識別碼；同一支程式可以有多個 process。工作目錄影響相對路徑，PATH 影響 shell 找到哪個可執行檔。'],['設定與結束','環境變數是 process 啟動時接收的設定，子程式通常繼承父程式的環境。它不是密碼保管庫。先用 Ctrl+C 停止前景程式；kill 預設傳送 SIGTERM，程式可處理後清理。只操作自己的實驗程式。']],
`# Linux / macOS / WSL 終端機\npwd\npython -c 'import os; print(os.getpid(), os.getcwd())'\nAPP_MODE=dev python -c 'import os; print(os.environ["APP_MODE"])'`,
['pwd 顯示工作目錄，os.getcwd() 應與其一致。','每次執行的 PID 可能不同，這是正常現象。','APP_MODE=dev 只為該次指令設定值。Windows PowerShell 改用 $env:APP_MODE="dev"，再執行 Python。'],
'在自己電腦建立 app.py，印出 PID、工作目錄、APP_MODE，再每秒印出 alive。從另一個終端找到它並正常停止；記錄觀察結果。',
`import os\nimport time\n\n# 印出 PID、工作目錄與 APP_MODE\nwhile True:\n    time.sleep(1)\n    print("alive", flush=True)`,
['使用 os.getpid()、os.getcwd()、os.getenv("APP_MODE", "dev")。','Linux/WSL 用 ps -p <你剛取得的PID>；PowerShell 用 Get-Process -Id <PID>。'],
`print(os.getpid(), os.getcwd(), os.getenv("APP_MODE", "dev"))\n# 在 while 前加入此行。觀察後 Ctrl+C；KeyboardInterrupt 為預期結果。\n# Linux/WSL：ps -p <PID>；kill <PID>\n# 停止後 ps 應不再顯示該 Python process。`,
[q('PATH 決定什麼？',['程式儲存資料的格式','shell 在哪些目錄找可執行檔','所有檔案權限'],1,'PATH 是搜尋可執行檔的路徑清單，不是 Python 資料庫。'),q('兩次執行同一支程式的 PID？',['可以不同','必定相同','就是檔案名稱'],0,'PID 識別執行中的程式，而不是原始碼檔案。')],
[['Python：os','https://docs.python.org/3.12/library/os.html'],['Ubuntu：命令列','https://ubuntu.com/tutorials/command-line-for-beginners']]);
lesson(5,
[['提交是可回到的快照','Git 工作目錄是你正在修改的檔案，staging area 是下次提交的內容，commit 是記錄下來的快照。git diff 看尚未暫存的差異，git diff --staged 看即將提交的差異。branch 是指向 commit 的名稱，不是完整複製一個資料夾。'],['合併衝突需要理解意圖','兩個分支改了同一段內容時 Git 可能無法決定。衝突不是資料全毀；讀取雙方修改、選出正確結果、刪除衝突標記，再 add 與 commit。merge 前先確保工作目錄乾淨。只在練習 repo 製造衝突。']],
`git init\ngit add README.md\ngit commit -m "docs: describe project"\ngit switch -c feature-notes\n# 編輯 README.md 後\ngit diff\ngit add README.md\ngit diff --staged\ngit commit -m "docs: add learning notes"`,
['第一次 commit 前需設定 Git user.name 與 user.email，這是提交署名，不是登入。','switch -c 建立分支；commit 留在當前分支。','切回原分支再 merge feature-notes。原分支可由 git branch 查詢，不要假設一定叫 main。'],
'建立練習 repo 與 README。從同一個 commit 建立兩個分支，各自修改同一行成不同文字並提交。合併時解衝突，最後記錄 git log --oneline --graph 的結果。',
`# 記錄你的操作與理由\n基礎 commit：\n分支 A 的意圖：\n分支 B 的意圖：\n最後保留的內容：\n驗證指令與結果：`,
['兩個分支必須從共同基礎分出，且改動同一行才容易產生衝突。','合併後用 git status，並搜尋 <<<<<<<、=======、>>>>>>>。'],
`1. base README 寫「課程」。\n2. branch-a 改成「Python 課程」並 commit。\n3. 從 base 建 branch-b 改成「架構課程」並 commit。\n4. 在 branch-b 執行 git merge branch-a。\n5. 解成「Python 與架構課程」，移除標記，add、commit。\n6. status 乾淨；log 圖顯示雙方歷史。`,
[q('git add 的作用？',['把內容放入下次提交的暫存區','直接釋出到 GitHub','自動解衝突'],0,'add 並不推送，也不等於 commit。'),q('出現 merge conflict 時先做什麼？',['刪掉整個 repo','理解雙方修改並決定結果','隨意保留全部標記'],1,'Git 無法自動判斷意圖，需由人決定最後內容。')],
[['Git：分支合併','https://git-scm.com/book/en/v2/Git-Branching-Basic-Branching-and-Merging']]);
lesson(6,
[['HTTP 是請求與回應','request 包含方法、路徑、headers 與可能存在的 body；response 包含狀態碼、headers 與 body。GET 取得資源，POST 常用於建立或提交，PATCH 做區域性修改。PUT 的語意是替換目標資源的表達，不只是另一種 PATCH。'],['網址背後的分層','DNS 查詢名稱對應的位址；HTTPS 建立受 TLS 保護的 HTTP 通訊。HTTP/1.1 與 HTTP/2 通常走 TCP，HTTP/3 則走 QUIC/UDP，所以「一定 TCP」不是普遍規則。400 類通常涉及請求或權限，500 類通常涉及伺服器失敗；各 API 還需定義具體錯誤契約。']],
`curl -i https://example.com\n# 對你自己的 API：\ncurl -i -X POST http://127.0.0.1:8000/students \\\n  -H 'Content-Type: application/json' \\\n  -d '{"name":"Alice"}'`,
['-i 同時顯示回應標頭與內容；觀察 status 與 Content-Type。','POST 範例須先有本機服務，連不上不是 JSON 驗證失敗。','401 通常代表缺少或無效身分驗證，403 代表拒絕存取；404 是否隱藏資源存在性要依安全政策設計。'],
'用 curl 或瀏覽器開發工具觀察一個 GET。寫出方法、URL、status、Content-Type 與 body 的前 100 字，並用自己的話畫出請求路徑。',
`方法：\nURL：\n狀態碼：\nContent-Type：\nBody 節錄：\nDNS、TLS、HTTP 各自負責：`,
['headers 與 body 通常以空白行分隔。','別把 HTTP status 與 HTML 裡的文字錯誤訊息混為一談。'],
`GET https://example.com；成功回應常為 200。\nContent-Type 說明資料格式，例如 text/html。\nDNS：名稱解析。TLS：加密與驗證通訊端身分。\nHTTP：定義應用層的請求與回應語意。\n實際回應以你觀察到的結果為準。`,
[q('HTTP/3 必須使用 TCP 嗎？',['必須','不必，使用 QUIC/UDP','沒有網路傳輸'],1,'不同 HTTP 版本有不同的傳輸方式。'),q('已登入但無權刪除課程，通常用？',['201','500','403'],2,'403 表示拒絕存取，不是建立成功或未知伺服器錯誤。')],
[['MDN：HTTP 概觀',MDN+'Web/HTTP/Overview']]);
lesson(7,
[['路由把網路接上函式','FastAPI 使用路徑與 HTTP 方法選擇 Python 函式。/students/3 的 3 是 path parameter；回傳 dict 或 list 可序列化成 JSON。先做最小 GET，再加建立和修改，逐一用 /docs 或 curl 驗證。'],['記憶體是練習用儲存','此階段的 dict 只存在於單一 process。重啟即消失，多個 worker 也不共享。找不到學生要明確回 404；不要回 200 加「找不到」。FastAPI 執行在自己的後端，GitHub Pages 只提供靜態檔案，不能替你執行 Python API。']],
`from fastapi import FastAPI, HTTPException\napp = FastAPI()\nstudents = {1: {"id": 1, "name": "Alice"}}\n\n@app.get("/students/{student_id}")\ndef get_student(student_id: int):\n    if student_id not in students:\n        raise HTTPException(status_code=404, detail="Student not found")\n    return students[student_id]`,
['建立 .venv，python -m pip install fastapi uvicorn，再存成 main.py。','啟動 python -m uvicorn main:app --reload；main 是檔名，app 是變數名。','請求 /students/1 應取得 Alice，/students/999 應為 404；/docs 可檢視契約。'],
'在本機新增 GET /students 回傳所有學生，以及 DELETE /students/{student_id}。DELETE 成功回 204 且無 body，不存在回 404。先保留記憶體儲存。',
`# 寫下路由與測試紀錄\nGET /students：\nDELETE /students/1：\n再次 DELETE /students/1：\n重啟後資料變化：`,
['204 可回 Response(status_code=204)。','刪除前檢查是否存在，再用 del students[student_id]。'],
`from fastapi import Response\n\n@app.get("/students")\ndef list_students():\n    return list(students.values())\n\n@app.delete("/students/{student_id}", status_code=204)\ndef delete_student(student_id: int):\n    if student_id not in students:\n        raise HTTPException(404, "Student not found")\n    del students[student_id]\n    return Response(status_code=204)`,
[q('這個 dict 在伺服器重啟後？',['自動變資料庫','恢復成程式中的初始值','永遠儲存刪除狀態'],1,'記憶體狀態不是持久化儲存。'),q('GitHub Pages 能直接執行 FastAPI 嗎？',['不能，需另外的後端執行環境','能，用 .py 檔即可','能，只需改 CSS'],0,'Pages 提供靜態檔案，後端需另行部署。')],
[['FastAPI：第一步',FAST+'first-steps/']]);
lesson(8,
[['schema 定義可接受的資料','Pydantic 模型定義欄位、型別與限制。建立請求與回應模型分開，避免使用者傳入內部欄位。Field 可約束長度或數值。部分型別預設可能轉換資料；如果需求必須嚴格拒絕轉換，明確啟用 strict。'],['區域性修改與缺欄位','PATCH 必須區分「沒有提供欄位」與「提供 null」。model_dump(exclude_unset=True) 只取明確提供的欄位。FastAPI 預設請求驗證失敗為 422；schema 驗證不取代資料庫約束、權限與業務規則。']],
`from pydantic import BaseModel, Field, ConfigDict\n\nclass StudentCreate(BaseModel):\n    model_config = ConfigDict(strict=True, extra="forbid")\n    name: str = Field(min_length=1, max_length=100)\n    age: int = Field(ge=0, le=120)`,
['strict=True 讓本範例不把 "18" 當整數接受。','extra="forbid" 拒絕未定義的欄位，例如 role="admin"。','測試 age=-1、缺 name、age="18"；API 接收此模型時應回 422。'],
'在 Week 7 的 POST /students 加上 StudentCreate，並使用伺服器產生 ID。傳送三組錯誤資料，記錄 422 回應裡指向的欄位。',
`正常請求：\n錯誤 1：\n錯誤 2：\n錯誤 3：\n伺服器如何產生 ID：`,
['建立成功可定義 201。不要相信使用者提供的 id 或 role。','name 長度限制不會自動排除全空白；若需求禁止空白名，另加驗證。'],
`@app.post("/students", status_code=201)\ndef create_student(data: StudentCreate):\n    new_id = max(students, default=0) + 1\n    item = {"id": new_id, **data.model_dump()}\n    students[new_id] = item\n    return item\n# 此 ID 策略只適合單 process 練習；正式系統用 DB 產生與約束。`,
[q('schema 能取代權限檢查嗎？',['能','不能','只有 name 可取代'],1,'資料格式正確不代表呼叫者有權操作。'),q('PATCH 沒有傳 name 和傳 name=null？',['意義必定相同','應當區分','都表示自動改名'],1,'未提供通常表示不修改，null 是否可接受需由契約決定。')],
[['FastAPI：欄位限制',FAST+'body-fields/'],['Pydantic：嚴格模式','https://docs.pydantic.dev/latest/concepts/strict_mode/']]);
lesson(9,
[['表格與約束','table 是同類記錄的集合，row 是一筆記錄。主鍵唯一識別資料；NOT NULL、CHECK、UNIQUE 把規則放進資料庫。應用程式驗證給出友善錯誤，資料庫約束則保護多個寫入端共同使用的資料。'],['查詢與安全寫入','SELECT 用 WHERE 篩選，ORDER BY 決定排序。對 Python 使用者輸入，交由驅動程式引數繫結，不能拼接 SQL。用交易管理寫入；關閉 API 後再查資料，才證明資料不是隻留在 process。']],
`CREATE TABLE students (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  name text NOT NULL,\n  age integer CHECK (age BETWEEN 0 AND 120)\n);\nINSERT INTO students(name, age) VALUES ('Alice', 18);\nSELECT id, name FROM students ORDER BY id;`,
['本機安裝 PostgreSQL 並建立練習資料庫；在 psql 或 SQL 工具執行。','IDENTITY 由資料庫產生 ID；PRIMARY KEY 防止重複。','Python psycopg 使用 execute("SELECT ... WHERE id = %s", (student_id,))，%s 是驅動引數位置，不是字串格式化。'],
'建立 students 表，寫入三筆資料。做一次 UPDATE、一次 DELETE；用 psycopg 引數查詢學生。把 API 接入後重啟，確認資料仍在。',
`建表 SQL：\n三筆資料與查詢結果：\nUPDATE / DELETE：\nPython 引數化查詢：\n重啟驗證：`,
['python -m pip install "psycopg[binary]"。連線字串從環境變數讀取。','記錄約束失敗：age=-1 應被拒絕。'],
`import os, psycopg\nwith psycopg.connect(os.environ["DATABASE_URL"]) as conn:\n    with conn.cursor() as cur:\n        cur.execute("SELECT id, name FROM students WHERE id = %s", (1,))\n        print(cur.fetchone())\n# 正常離開 context 會提交，例外則回滾。不要把真實連線密碼寫進筆記。`,
[q('為什麼還要 DB 約束？',['防止其他寫入端破壞規則','只為排版','取代全部測試'],0,'資料庫是共用的完整性邊界，不能只依賴一個 API。'),q('安全查詢使用者提供的 ID 應？',['用 f-string 插入 SQL','使用引數繫結','直接刪除 WHERE'],1,'驅動分開處理 SQL 與值，減少 SQL 注入風險。')],
[['PostgreSQL：SQL 教程',PG+'tutorial-sql.html'],['psycopg：引數','https://www.psycopg.org/psycopg3/docs/basic/params.html']]);
lesson(10,
[['從關係辨識資料','一位教師可以擁有多門課程，這是 1:N。學生可選多門課程，一門課程也可有多位學生，是 N:M，需要 Enrollment 連線。不要把所有課程 ID 塞進逗號字串，否則難以約束與查詢。'],['主鍵、外來鍵與重複規則','FK 指向另一表的合法記錄，UNIQUE 定義不允許重複的組合。Enrollment 的 (student_id, course_id) 應唯一。刪除課程時是否連帶刪除作業要先決定；CASCADE 是業務決定，不應為方便亂加。']],
`CREATE TABLE enrollments (\n  student_id bigint REFERENCES students(id),\n  course_id bigint REFERENCES courses(id),\n  enrolled_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY(student_id, course_id)\n);`,
['需先建立 courses 表，且 id 為主鍵。','組合主鍵同時識別一筆選課並防止重複選課。','Enrollment 可以有自己的屬性，例如 enrolled_at，而不只是連線。'],
'設計 User、Course、Enrollment、Assignment、Submission 的 ER 圖。標註 PK/FK 與基數，再寫出「一份作業每人只能有一份當前繳交」的約束。',
`User 欄位：\nCourse 欄位：\nEnrollment 欄位與唯一規則：\nAssignment 欄位：\nSubmission 欄位與唯一規則：\n關係與刪除行為：`,
['Submission 引用 Assignment 與 User；唯一組合可為 (assignment_id, student_id)。','若要儲存多次繳交，改用版本表，明確區分當前記錄與歷史。'],
`User 1:N Course（教師擁有課程）\nUser N:M Course（透過 Enrollment）\nCourse 1:N Assignment\nAssignment 1:N Submission；User 1:N Submission\nUNIQUE(assignment_id, student_id) 保護當前繳交。\n歷史版本另建 SubmissionVersion，不與當前唯一約束混用。`,
[q('學生與課程 N:M 通常怎麼表示？',['一欄逗號字串','連線表 Enrollment','只存在前端'],1,'連線表支援外來鍵與關係本身的屬性。'),q('UNIQUE(assignment_id, student_id) 保證？',['所有人只能修一堂課','每人對同一作業至多一筆當前記錄','教師才能登入'],1,'組合唯一約束的作用依欄位組合決定。')],
[['PostgreSQL：約束',PG+'ddl-constraints.html']]);
lesson(11,
[['交易讓一組操作一起完成','BEGIN 後多個操作在 COMMIT 時提交；失敗則 ROLLBACK。原子性防止只扣款卻未入帳。ACID 的一致性依賴你寫對約束和邏輯；交易不會自動知道「餘額不能為負」的業務規則。隔離層級影響並行時看到的狀態。'],['索引需要量測','索引像額外整理的查詢結構，適合特定篩選與排序，但佔用空間並增加寫入成本。EXPLAIN ANALYZE 真正執行查詢，故只用於安全的查詢或可回滾的測試。小表可能用循序掃描更快，不能只以是否用索引判斷好壞。']],
`BEGIN;\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\nROLLBACK;\n-- 此時兩邊的變動都不應留下\nCREATE INDEX students_name_idx ON students(name);\nEXPLAIN ANALYZE SELECT * FROM students WHERE name = 'Alice';`,
['accounts 需先在練習 DB 建立且放入兩個帳戶。','故意 ROLLBACK，觀察兩筆餘額都恢復。正式扣款需檢查餘額、受影響列數與鎖定策略。','對足夠資料量比較索引前後計畫、耗時與測試環境，別用單次結果下結論。'],
'在練習 DB 做一組兩步操作，第二步故意違反 CHECK，確認回滾。再建立 1 萬筆學生測試資料，比較精確名稱查詢的索引前後計畫。',
`交易 SQL：\n故意失敗的位置：\n回滾後查詢：\n索引前後計畫：\n資料量與測量限制：`,
['錯誤後先 ROLLBACK 才能繼續使用該交易。','記錄 actual time、rows 與使用的掃描方式，重複數次。'],
`BEGIN；新增合法學生；新增 age=-1 的學生觸發 CHECK；ROLLBACK。\n驗證第一筆也不存在。\n索引實驗可用 generate_series 產生資料，ANALYZE 更新統計。\n結論需寫「在此資料量、查詢與環境下」，而非索引永遠較快。`,
[q('有交易是否一定不會發生並行錯誤？',['一定','不一定，還看隔離與邏輯','只有 INSERT 不會'],1,'交易需搭配合適的隔離、鎖定與重試策略。'),q('每欄都建索引的代價？',['沒有代價','增加空間與寫入維護','自動減少備份大小'],1,'每次寫入可能需維護多個索引。')],
[['PostgreSQL：交易',PG+'tutorial-transactions.html'],['PostgreSQL：EXPLAIN',PG+'using-explain.html']]);
lesson(12,
[['HTML 描述意義','標題有階層，main 包含主要內容，form 包含使用者要提交的欄位。label 讓欄位有可辨識名稱，button 表示操作。語意元素幫助鍵盤與輔助工具操作；不是把全部內容都做成 div。'],['表單仍需要後端驗證','required 和 minlength 改善使用體驗，但可被繞過。form 的 action 決定提交位置，method 決定 GET 或 POST；預設提交可讓頁面跳轉。HTML 本身不會建立資料庫。先做靜態表單，再在 Week 14 接入 API。']],
`<form id="student-form">\n  <label for="name">姓名</label>\n  <input id="name" name="name" required maxlength="100">\n  <button type="submit">新增學生</button>\n</form>\n<table>\n  <caption>學生清單</caption>\n  <thead><tr><th scope="col">姓名</th></tr></thead>\n  <tbody><tr><td>Alice</td></tr></tbody>\n</table>`,
['label 的 for 對應 input 的 id，點文字也可聚焦欄位。','name 是表單欄位的提交名稱，id 則是頁面識別。','目前只是結構，不宣稱已寫入資料庫。'],
'做一頁學生清單與新增表單，含姓名、年齡、錯誤訊息區。只用鍵盤 Tab 操作，確認每個欄位可聚焦且有標籤。',
`<!doctype html>\n<html lang="zh-Hant">\n<meta charset="utf-8">\n<title>學生管理</title>\n<main>\n  <h1>學生管理</h1>\n  <!-- 加入表單與清單 -->\n</main>\n</html>`,
['年齡可用 type="number" min="0" max="120"；後端仍驗證。','驗收紀錄寫下 Tab 順序，不只貼螢幕截圖。'],
`兩個 label/input 正確對應；submit 按鈕可由鍵盤啟動。\n清單用 table、caption、thead、tbody、th。\n錯誤區可使用 role="status"，並提供可讀文字。\n靜態頁面尚未接上資料儲存，這是本週的邊界。`,
[q('required 能取代後端驗證嗎？',['能','不能','只有手機需要後端'],1,'使用者可直接呼叫 API，繞過表單。'),q('label 的 for 對應？',['input 的 id','資料庫 ID','CSS 顏色'],0,'正確連結讓欄位有明確名稱並支援聚焦。')],
[['MDN：表單',MDN+'Learn_web_development/Extensions/Forms']]);
lesson(13,
[['盒模型與排版','content、padding、border、margin 決定元素佔用空間。box-sizing:border-box 讓指定寬度包含 padding 與 border。Flexbox 適合一個方向的排列；Grid 適合列與欄的配置。主要版面跟著內容流動，比以 absolute 硬定位更能適應文字長度。'],['響應式與可讀性','手機寬度下將卡片改單欄，導覽允許換行；避免整頁橫向溢位。長程式碼可在自己的區塊水平捲動。保留鍵盤 focus 的視覺指示，不要只依顏色顯示完成或錯誤。']],
`* { box-sizing: border-box; }\n.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }\n.card { padding: 20px; border: 1px solid #ccc; }\n@media (max-width: 700px) { .cards { grid-template-columns: 1fr; } }\nbutton:focus-visible { outline: 3px solid #315dff; outline-offset: 3px; }`,
['minmax(0,1fr) 允許欄位縮小，減少長內容撐開版面。','media query 依視窗寬度選擇樣式；不需知道手機品牌。','focus-visible 讓鍵盤操作位置可見。'],
'替 Week 12 加入導覽、卡片與表單樣式。在 375、768、1280px 寬度檢查文字、按鈕與水平捲動，寫下修正紀錄。',
`/* 先設定盒模型，再做 grid 與 media query */\n* { box-sizing: border-box; }\n/* 記錄三個寬度的驗收結果 */`,
['表單 input 設 max-width:100%；Grid 子項可設 min-width:0。','不要把 outline:none 當成美化的預設。'],
`375px：單欄，按鈕可點，正文無水平溢位。\n768px：可採兩欄；依實際內容決定。\n1280px：限制主要文字行寬，不把段落拉滿全螢幕。\n長程式碼放 overflow:auto 的 pre 區塊，保持正文可讀。`,
[q('border-box 的寬度包含？',['padding 和 border','只有文字','margin 也必定包含'],0,'margin 在盒子之外，不包含於 border-box 寬度。'),q('主要版面全用 absolute 的問題？',['難以適應內容長度與視窗','一定比較快','會自動完成表單'],0,'脫離正常排版流可能導致內容互相遮擋。')],
[['MDN：盒模型',MDN+'Learn_web_development/Core/Styling_basics/Box_model']]);
lesson(14,
[['非同步不等於忽略錯誤','fetch 回傳 Promise，await 等待結果。HTTP 404 或 500 通常不使 fetch 自動 reject；需檢查 response.ok。網路故障則可能拋出例外。把 loading、success、empty、error 當成明確狀態。'],['DOM 與資料邊界','以 textContent 顯示使用者文字，避免把資料當 HTML。跨來源請求可能需要後端正確設定 CORS；CORS 不是 API 權限系統。不要把後端管理金鑰放入前端。先本機串接，再討論 HTTPS 公開部署。']],
`async function loadStudents() {\n  const response = await fetch("http://127.0.0.1:8000/students");\n  if (!response.ok) throw new Error("HTTP " + response.status);\n  const students = await response.json();\n  document.querySelector("#count").textContent = String(students.length);\n}`,
['本機前端與 API 的來源包含 scheme、host、port；不同 port 也是跨來源。','response.json() 也可能因回應格式錯誤而失敗。','外層 try/catch 顯示錯誤，再提供重試；不要在 catch 假裝成功。'],
'完成學生列表與 POST 表單。送出時停用按鈕以避免重複點選；完成後在 finally 恢復。停止 API，確認畫面顯示可理解的錯誤。',
`async function submitStudent(data) {\n  // loading → fetch → 檢查 status → 更新列表\n  // catch 顯示錯誤；finally 恢復按鈕\n}`,
['POST 加 Content-Type: application/json 與 JSON.stringify(data)。','按鈕停用改善體驗，但伺服器仍需防止重複寫入。'],
`try {\n  button.disabled = true;\n  const r = await fetch(api + "/students", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(data)});\n  if (!r.ok) throw new Error("新增失敗：" + r.status);\n  await loadStudents();\n} catch (e) { status.textContent = e.message; }\nfinally { button.disabled = false; }`,
[q('fetch 收到 HTTP 500 通常？',['需自行檢查 ok/status','自動當作成功資料','必定 reject'],0,'網路成功送回回應與應用操作成功是兩件事。'),q('顯示使用者名字應優先？',['innerHTML','textContent','eval'],1,'textContent 將內容當文字，避免直接解讀成 HTML。')],
[['MDN：使用 Fetch',MDN+'Web/API/Fetch_API/Using_Fetch']]);
lesson(15,
[['編譯階段的契約','TypeScript 在開發與編譯時檢查型別，輸出 JavaScript 供瀏覽器執行。interface 定義資料形狀；strict 模式能揭露可能缺值等問題。型別檢查不等於執行時驗證，外部 API 回來的 JSON 仍可能不符合宣告。'],['不要用 any 蓋掉問題','unknown 要先判斷才能使用，any 則會略過很多檢查。不要以 as Student[] 假裝已驗證。前端型別與後端 schema 可由契約生成，但仍需確認版本與執行時資料。']],
`interface Student { id: number; name: string; }\nfunction displayName(student: Student): string { return student.name; }\nconst alice: Student = { id: 1, name: "Alice" };\nconsole.log(displayName(alice));`,
['在練習專案安裝 typescript，設定 strict:true。','把 name 改成 123，執行 npx tsc --noEmit 觀察錯誤。','瀏覽器不能把此介面當成輸入驗證器，資料進入時仍要判斷。'],
'將 Week 14 的學生資料型別化，寫 isStudent(value: unknown) 檢查 id 與 name。用錯誤 JSON 證明執行時驗證存在。',
`interface Student { id: number; name: string; }\nfunction isStudent(value: unknown): value is Student {\n  // 先判斷非 null 物件，再判斷欄位\n  return false;\n}`,
['typeof null 是 object，因此要排除 null。','type guard 回傳 boolean，並告訴編譯器成功時可縮小型別。'],
`function isStudent(value: unknown): value is Student {\n  if (typeof value !== "object" || value === null) return false;\n  const v = value as Record<string, unknown>;\n  return typeof v.id === "number" && Number.isInteger(v.id) && typeof v.name === "string";\n}`,
[q('interface 會驗證下載的 JSON 嗎？',['不會，需執行時檢查','會自動拒絕 HTTP','會改寫資料庫'],0,'TypeScript 的型別在輸出 JS 時會被移除。'),q('unknown 相較 any 的用途？',['要求先縮小型別再使用','自動取得資料','不需要檢查'],0,'unknown 保留不確定性，避免任意操作未知值。')],
[['TypeScript：型別縮小','https://www.typescriptlang.org/docs/handbook/2/narrowing.html']]);
lesson(16,
[['驗證身分與儲存密碼','Authentication 確認你是誰；Authorization 判斷你能做什麼。密碼需使用專門的慢速密碼雜湊函式與 salt，例如成熟函式庫的 Argon2id；不能用可解密儲存或單純 SHA-256 代替。登入錯誤避免揭露帳號是否存在。'],['session、cookie 與 JWT','cookie 是瀏覽器儲存與自動送出的機制，session 是伺服器儲存登入狀態的方案；JWT 是一種 token 格式，它們不是互斥的分類。JWT 簽章通常不隱藏內容。登出、過期、撤銷與 CSRF 防護都要設計。練習可先採伺服器 session，正式環境需 HTTPS。']],
`# 概念流程，不是完整可部署的登入系統\nregister: validate → password_hash → store user\nlogin: verify password → generate random session ID → store session\nresponse: Set-Cookie with HttpOnly; Secure; SameSite\nlogout: revoke server session → expire cookie`,
['使用成熟函式庫產生與驗證雜湊，不自己寫加密。','Secure cookie 需要 HTTPS；本機 HTTP 開發設定需與正式環境分開。','SameSite 是一部分防護，Cookie 驗證的修改操作仍需評估 CSRF token 或其他防護。'],
'在獨立練習專案完成註冊、登入、私人資料與登出。記錄匿名、錯密碼、成功登入、登出後重用原 session 的結果。不得使用真實學生帳號。',
`使用的雜湊函式庫：\nSession 儲存位置：\nCookie 設定：\n過期與撤銷規則：\n四個測試結果：`,
['先閱讀 FastAPI 安全教程；理解示範 token 與你的 session 方案差異。','登出測試不能只看畫面，還要重新用原 session 呼叫私人 API。'],
`驗收：DB 沒有明文密碼；登入成功才建立 session。\n私人 API 查 session 有效性；登出刪除或撤銷 session。\nCookie 限制、CSRF、限速與過期策略寫入設計。\n此練習不等於已達正式環境安全標準，需經後續安全與恢復測試。`,
[q('JWT 有簽章代表 payload 是秘密嗎？',['不代表','代表全部加密','代表永不過期'],0,'一般簽章 JWT 內容可讀取，簽章保護完整性。'),q('儲存密碼的合理方式？',['明文','快速單次 SHA-256','成熟的密碼雜湊方案'],2,'密碼雜湊需抵抗離線猜測，選適合的演演算法與引數。')],
[['OWASP：密碼儲存',OWASP+'Password_Storage_Cheat_Sheet.html'],['FastAPI：安全',FAST+'security/']]);
lesson(17,
[['角色不是全部權限','RBAC 用角色分配操作，仍需判斷資源範圍。teacher 不能因此修改所有教師的課程，TA 只能批改被指派的課程。權限判斷通常是身分有效、角色允許、資源關係成立。預設拒絕，不相信前端傳來的 role。'],['在可信邊界執行','每個 API 都在後端檢查；直接輸入 URL 或換資源 ID 也不能越權。資料庫 RLS 可增加另一層保護，但需理解執行身分與政策。管理員例外必須明確定義與稽核，而非到處寫 if admin。']],
`def can_grade(user, course, assigned_ta_ids):\n    return (user.role == "admin"\n        or course.teacher_id == user.id\n        or (user.role == "ta" and user.id in assigned_ta_ids))`,
['這是 domain 判斷函式，呼叫前需從可信 session 取得 user。','課程關係與 TA 指派從 DB 取得，不由請求者自行填寫。','回傳允許不代表已儲存成績；儲存還需驗證資料與交易。'],
'建立四角色 × 五操作的矩陣，再加入課程 A/B 的範圍。測試學生、未指派 TA、另一位教師直接呼叫批改 API。',
`功能 | Student | TA | Teacher | Admin\n讀課程：\n繳作業：\n批改：\n發布：\n管理帳號：\n資源範圍與拒絕測試：`,
['至少有一個「同角色但不同課程」的拒絕案例。','測試本人資料與他人資料，不只測 admin 頁面。'],
`學生只能繳自己的作業；TA 僅批改指派課程。\n教師僅管理所屬課程；管理員依明確管理政策。\n後端檢查 session → 操作 → 資源關係；失敗拒絕且不修改資料。\n矩陣需列出未登入狀態。`,
[q('teacher 可否因此修改任何課程？',['必定可以','還要檢查資源範圍','只看前端按鈕'],1,'角色與資源所有權是不同維度。'),q('可信的 role 從哪來？',['使用者 POST 的 role','前端 localStorage','驗證過的身分與伺服器資料'],2,'呼叫者控制的欄位不能當授權依據。')],
[['OWASP：授權',OWASP+'Authorization_Cheat_Sheet.html']]);
lesson(18,
[['不同層級回答不同問題','unit 測試可獨立驗證業務規則，integration 驗證 API、DB 等元件合作，E2E 從使用者流程驗證全系統。名稱與邊界在團隊間可能不同，先定義本專案分層。不要只追求測試數量。'],['測試要可重複','測試資料庫與正式資料隔離；每次測試可重設資料。權限失敗除 status 外，還要確認沒有副作用。測試應包含錯誤輸入、他人資源、重複操作及依賴失敗，而不只是首頁載入。']],
`def test_unassigned_ta_cannot_grade(client, ta_session, submission):\n    r = client.patch(f"/submissions/{submission.id}/grade",\n        json={"score": 80}, cookies=ta_session)\n    assert r.status_code == 403\n    assert read_grade(submission.id) is None`,
['client、session、submission 為你定義的 fixture，範例說明測試形狀。','最後一行確認拒絕操作沒有偷改資料。','先讓測試在有缺陷的實作上失敗，修正後才透過。'],
'寫 3 個 unit、3 個 API/DB integration、1 個 E2E：學生登入、選課、繳作業。至少一題先寫失敗測試再修程式。',
`Unit 規則：\nIntegration 邊界：\nE2E 流程：\n先失敗再修正的證據：\n資料重設方式：`,
['不要用正式 DB URL；測試啟動前檢查環境名稱。','E2E 需固定測試資料，避免依賴別人前一次操作。'],
`unit：成績範圍、截止時間、權限函式。\nintegration：成功寫入、越權無副作用、無效 FK 被拒絕。\nE2E：瀏覽器完成核心流程並從 API/DB 確認結果。\n保留修正前後的測試輸出，不只報告「有測試」。`,
[q('403 測試還應檢查？',['字型大小','沒有資料副作用','一定呼叫三次'],1,'回拒絕但資料已被修改，仍是嚴重錯誤。'),q('integration 測試適合驗證？',['API 與 DB 合作','僅函式命名','僅 README 字數'],0,'它跨越元件邊界，能揭露介接錯誤。')],
[['FastAPI：測試',FAST+'testing/'],['pytest：fixture','https://docs.pytest.org/en/stable/how-to/fixtures.html']]);
lesson(19,
[['日誌讓事件可追查','用穩定欄位記錄時間、request_id、動作與結果。正常拒絕與系統失敗用不同事件名稱。關聯 ID 讓一個請求的多段記錄串起來。不要記錄密碼、token、完整私人訊息或過多個資。'],['錯誤對外與對內不同','對外回傳可理解且穩定的錯誤程式碼；對內儲存 stack trace 與必要背景。未知例外不應把原始 SQL 或秘密傳給使用者。except 捕捉可處理的錯誤，無法處理則讓它上拋並由統一邊界記錄。']],
`import logging\nlogger = logging.getLogger(__name__)\ntry:\n    save_submission()\nexcept DatabaseError:\n    logger.exception("submission_save_failed", extra={"request_id": request_id})\n    raise`,
['DatabaseError、save_submission 為專案自己的實作或驅動例外。','logger.exception 在 except 內包含 stack trace。','logging extra 不會自動輸出 JSON；需要 formatter 或集中式日誌設定。'],
'設計五個日誌欄位，在三種失敗下觀察：驗證失敗、權限拒絕、DB 斷線。確認同一請求可用 request_id 找到，且無密碼或 token。',
`日誌欄位：\n錯誤程式碼：\n三種失敗的範例：\n敏感資料排除策略：`,
['以假帳號測試，不把真實個資貼進教材筆記。','分清可預期的 4xx 與需要告警的 5xx。'],
`欄位：timestamp、request_id、event、status、duration_ms。\n外部：{code:"SUBMISSION_SAVE_FAILED", request_id:"..."}。\n內部：例外型別與 stack trace，限制存取與儲存時間。\n拒絕權限寫事件；DB 故障可累積錯誤率並觸發告警。`,
[q('extra 欄位是否自動產生 JSON log？',['是','否，需要輸出設定','會寫資料庫'],1,'標準 logging 需合適 formatter 才呈現結構化欄位。'),q('哪些不應寫入一般日誌？',['request_id','密碼與 session token','status'],1,'日誌容易被複製與集中儲存，秘密不應留在其中。')],
[['Python：Logging','https://docs.python.org/3.12/howto/logging.html']]);
lesson(20,
[['Image 與 Container','image 是包含程式與執行依賴的封裝；container 是從 image 啟動的執行個體。Docker 改善環境重現，但不保證安全、資料備份或完全相同的主機行為。compose 定義多服務與網路，不等於 Kubernetes。'],['資料必須有儲存位置','container 可寫層不是可靠資料儲存策略。PostgreSQL 使用 volume，API 連線到 compose 服務名稱 db，而非自己的 localhost。刪除 volume 會刪資料；不要把 down -v 當成一般停止指令。啟動順序也不等於依賴已就緒。']],
`# Dockerfile：放在 FastAPI 專案\nFROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nCMD ["uvicorn", "main:app", "--host", "0.0.0.0", "--port", "8000"]`,
['requirements 包含 fastapi、uvicorn 與你的 DB driver，按專案記錄版本。','加 .dockerignore 排除 .venv、.git、.env，避免把本機秘密封進 image。','compose 的 API 使用 db:5432；瀏覽器則用你發布到主機的 port。'],
'撰寫 compose.yaml 啟動 API 與 PostgreSQL，宣告命名 volume 和 DB healthcheck。新增記錄，重建 API 與 DB container 後查回資料。',
`services:\n  api:\n    build: .\n    ports: ["8000:8000"]\n    # DATABASE_URL 從開發環境提供\n  db:\n    image: postgres:17\n    # 加設定、healthcheck 與 volume\nvolumes:\n  pgdata:`,
['PostgreSQL 17 的資料 volume 掛載 /var/lib/postgresql/data；不同主版本查官方 image 檔案。','只用假的本機密碼；不要把 .env 加入 Git。'],
`db 使用 pgdata:/var/lib/postgresql/data；healthcheck 用 pg_isready。\napi depends_on 的條件設 service_healthy，但 API 仍需處理執行時 DB 失敗。\ndocker compose up --build；新增資料；docker compose down；再 up。\n記錄資料還在，且說明 down -v 會移除 volume。`,
[q('image 與 container 的關係？',['封裝與執行個體','完全相同','兩者都是 DB'],0,'同一 image 可啟動多個 container。'),q('compose 裡 API 的 localhost 指向？',['API container 自己','自動指向 db','你的雲端 DB'],0,'不同服務透過網路與服務名稱互相連線。')],
[['Docker：Compose','https://docs.docker.com/compose/'],['PostgreSQL image','https://hub.docker.com/_/postgres']]);
lesson(21,
[['程式與設定分開','同一份程式在不同環境使用不同設定。development 可用假資料，staging 演練部署，production 提供正式服務。缺必要設定應在啟動時明確失敗，不要偷偷連到預設正式 DB。'],['秘密有完整生命週期','.gitignore 只阻止未追蹤檔案，不會清除已提交的秘密。曾洩漏的金鑰要撤銷與替換，再處理歷史。前端打包內容可被使用者讀取，不論變數名稱是否有 SECRET。環境變數本身也需控制讀取與日誌輸出。']],
`import os\nDATABASE_URL = os.environ["DATABASE_URL"]\nAPP_ENV = os.environ.get("APP_ENV", "development")\n\n# .env.example 只放名稱與假的示例\n# DATABASE_URL=postgresql://dev_user:placeholder@localhost/learning`,
['os.environ[...] 缺值會報錯，有助於及早發現設定問題。','Python 不會自動讀 .env；使用環境注入或明確的設定函式庫。','真實值由部署設定或秘密管理機制注入，不存進 repo。'],
'建立 .env.example 與 .gitignore，列出三環境的差異。在不印出秘密的前提下檢查 Git 追蹤內容；移除必要變數，確認啟動明確失敗。',
`必要設定名稱：\n.env.example：\n三個環境差異：\n缺值測試：\n金鑰洩漏後的處理順序：`,
['檢查 git ls-files，確認 .env 不在追蹤清單。','不要在公開截圖或 console.log 中印出 DATABASE_URL。'],
`忽略 .env、.venv 與私人檔案；example 留假值。\n缺 DATABASE_URL 直接停止啟動並報設定名稱，不印內容。\n洩漏：撤銷舊金鑰 → 換新 → 審查使用紀錄 → 清理歷史。\n只新增 .gitignore 無法撤回已洩漏金鑰。`,
[q('已提交的秘密新增到 .gitignore 就安全嗎？',['是','否，需撤銷替換並處理歷史','重新整理即可'],1,'先前提交仍包含秘密；忽略檔案不會撤銷外洩的金鑰。'),q('前端環境變數可放管理金鑰嗎？',['可以','不可以，打包結果可讀','改名就安全'],1,'前端執行環境不適合儲存後端秘密。')],
[['GitHub：移除敏感資料','https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/removing-sensitive-data-from-a-repository']]);
lesson(22,
[['CI 是自動重現驗證','每次 push 或 PR 啟動乾淨環境，安裝依賴、執行測試與建置。綠燈只代表配置的檢查透過，不證明沒有任何 bug。先確保本機測試可重複，再移到 CI。'],['部署需要順序與恢復','CD 在檢查成功後部署。失敗必須停止後續發布；部署機密與權限最小化。PR 來自外部的程式碼不應取得正式秘密。資料庫 migration 與回滾需另外設計，不是 git revert 就能恢復資料。']],
`name: Test\non: [push, pull_request]\npermissions:\n  contents: read\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: '3.12'\n      - run: python -m pip install -r requirements.txt\n      - run: python -m pytest`,
['存為 .github/workflows/test.yml；依賴需包含 pytest。','版本為教學範例，實際專案應審查 action 版本並考慮固定 commit。','加一個必敗 assert，確認 CI 紅燈，再修回來。'],
'在練習 repo 加 CI，做一次故意失敗與修正。記錄兩個 run URL；說明部署如何依賴測試結果與避免向 PR 暴露秘密。',
`失敗 run：\n修正 run：\n測試執行指令：\n部署的依賴：\n權限與秘密：`,
['測試工作和部署工作分開時，部署用 needs:test。','測試跑不到也是失敗，不要只看沒有紅字。'],
`故意讓一個測試失敗，workflow conclusion=failure；修正後 success。\n部署 job needs:test，只有允許分支及成功結果可部署。\nPR 驗證不讀正式秘密；不以 pull_request_target 執行不可信程式碼。`,
[q('CI 綠燈表示？',['所有配置的檢查透過','永遠沒有 bug','自動完成架構審查'],0,'品質界線取決於你配置了哪些檢查。'),q('部署 job 如何等待 test？',['只寫在檔案下方','用 needs 明確依賴','靠執行時間猜測'],1,'不同 jobs 可能並行，需明確宣告依賴。')],
[['GitHub Actions：Python','https://docs.github.com/en/actions/use-cases-and-examples/building-and-testing/building-and-testing-python']]);
lesson(23,
[['需求從使用情境開始','列出 actor、想完成的事、成功與失敗條件。功能需求描述系統做什麼；非功能需求定義速度、可用性、安全、可維運等品質。把「快速」改成可量測的條件，並標明是假設或已確認。'],['限制、範圍與驗收','預算、時程、既有系統與法規是限制。每條需求要有識別碼與驗收方式。十萬註冊會員不等於十萬人同時使用；尖峰請求量、資料量與檔案大小才影響設計。先定問題，再選框架。']],
`REQ-01：已選課學生可在截止前提交作業。\n驗收：本人成功；未選課拒絕；截止後拒絕。\nNFR-01（待確認假設）：50 個同時操作下，95% 讀取請求 < 500ms。\n限制：兩人維護，月預算需另確認。\n不含：本期不提供直播。`,
['角色 + 行動 + 邊界讓需求可驗證。','效能數字是練習假設，需指定測試環境與測量方式。','不含範圍使「完成」有界線，不代表永遠不做。'],
'拿圖書館借還系統寫 6 條功能需求、3 條品質需求、3 個限制。列出尚未知道的問題，每條需求附驗收案例。',
`Actors：\n功能需求與驗收：\n品質需求與量測：\n限制：\n假設與待確認：\n本期不含：`,
['逾期、同一本書多人借閱、遺失與帳號停權都可成為情境。','先不寫 React、Redis 等解法，除非是既有限制。'],
`借書：有效讀者、可借館藏才能借；已有借閱不可重複。\n還書：記錄歸還時間並更新可借狀態。\n品質：指定尖峰負載下的回應時間、可用性測量視窗與恢復目標。\n每條需求都有成功、拒絕和例外案例。`,
[q('十萬會員是否等於十萬並行使用者？',['是','否','固定除以二即可'],1,'並行與請求率需由使用行為或測量估算。'),q('可驗收的需求？',['系統很快','指定負載下 p95 小於指定時間','使用最新框架'],1,'需要明確指標、條件與測量方式。')],
[['Google SRE：SLO','https://sre.google/workbook/implementing-slos/']]);
lesson(24,
[['用層級控制細節','C4 Context 顯示系統、使用者與外部依賴，回答系統在環境中的位置。Container 放大系統內部，顯示應用與資料儲存責任、技術與通訊。此處 container 是架構抽象，不代表 Docker container。'],['圖的讀者與邊界','每個方塊要有名稱與責任，每條線有方向與資料/協定。Email provider 是外部系統，DB 可是內部資料儲存。把不同環境的部署機器、複本與負載平衡留在部署圖，避免混淆抽象層級。']],
`Context：學生、教師 → 學習平臺 → 郵件服務\nContainer：\nWeb UI：顯示教材與提交表單\nAPI：執行規則與權限\nPostgreSQL：儲存課程與繳交\nObject Storage：儲存附件\nAPI → PostgreSQL：SQL；API → Storage：HTTPS`,
['Context 不需放 route 或 class。','Container 圖描述責任如何分配；UI 和 API 可在同一部署內仍作不同責任説明。','是否獨立 deploy 取決於設計，不由圖上方塊自動決定。'],
'替圖書館系統畫 Context 與 Container 兩張圖。每個節點寫一句責任，每條線標方向、內容與協定；說明哪一條是信任邊界。',
`Context 節點：\nContainer 節點：\n連線與協定：\n信任邊界：\n圖的讀者：`,
['先限定一個系統範圍，外部登入服務不畫成自己擁有。','可用 Mermaid 或繪圖工具，重點是讀者能看懂。'],
`Context：讀者/館員操作借閱系統；系統發信給外部服務。\nContainer：Browser、API、DB、附件儲存；各寫責任。\nBrowser→API HTTPS 跨越使用者到後端的信任邊界。\n不要把 UI 元件、DB 表與實體伺服器混在同一層。`,
[q('C4 container 必然是 Docker 嗎？',['是','不是，是應用或資料儲存抽象','只指前端'],1,'C4 與容器執行平臺是不同概念。'),q('複本與負載平衡放哪較適合？',['Context 圖','部署圖','class 圖'],1,'部署圖說明環境中的執行例項與基礎設施。')],
[['C4：Container','https://c4model.com/diagrams/container'],['C4：Context','https://c4model.com/diagrams/system-context']]);
lesson(25,
[['資料有整個生命週期','每類資料要知道誰建立、誰有權讀寫、何時封存與刪除。帳號刪除會牽動繳交、討論、附件與稽核記錄；不能只刪 User 一列就當完成。儲存年限需依需求與適用規範確認，不在教材中任意指定。'],['歷史與一致性','當前值與歷史版本分開可以避免覆寫證據。DB 與檔案儲存之間通常不能以一個本機 DB transaction 全部提交，需狀態機、補償與重試。soft delete 不是資料已永久刪除，備份與快取也要處理。']],
`Submission：當前狀態與 current_version_id\nSubmissionVersion：版本、內容、作者、created_at\nAttachment：storage_key、status(pending/ready/deleting)\nDeletionJob：目標、狀態、重試次數\nAudit：事件與必要識別資訊，依政策儲存`,
['version 不以覆寫舊內容實作；保留來源與時間。','附件先 pending，成功上傳再 ready，失敗可清理。','刪除工作明確追蹤，外部服務失敗不被假裝成成功。'],
'為 User、Submission、Attachment、Audit 做生命週期表。畫帳號刪除流程，涵蓋檔案失敗、重試、備份及完成的定義。',
`資料 | Owner | 讀寫範圍 | 儲存條件 | 刪除/封存\n帳號刪除步驟：\n外部儲存失敗處理：\n備份與稽核政策：`,
['把「停用登入」與「完成資料刪除」分開。','所有權是管理責任，與法律上的所有權不應混為一談。'],
`先停用 session 與寫入刪除請求；DB 標記 deleting。\n背景工作刪附件並確認結果；失敗保留狀態與重試。\n依政策去識別化或刪除內容，記錄最少稽核資訊。\n備份儲存和恢復後再刪除規則要寫清楚。`,
[q('soft delete 是否等於永久刪除？',['是','否','看按鈕顏色'],1,'資料可能仍在 DB、備份與外部儲存。'),q('DB transaction 可自動回滾外部儲存刪除嗎？',['可以','通常不行，需另設流程','只要 COMMIT 即可'],1,'外部服務不自動參加同一個 DB 交易。')],
[['PostgreSQL：資料定義',PG+'ddl.html']]);
lesson(26,
[['契約涵蓋的不只有路徑','每個 endpoint 記錄方法、path、schema、狀態碼、權限與副作用。OpenAPI 可描述介面，仍需文字說明業務規則。列表介面要定義排序、分頁與最大頁面大小，避免無限讀取。'],['重複與並行修改','POST 重試可能重複建立資料，可用 idempotency key 配合伺服器儲存結果與唯一約束。PATCH 並行修改可用版本號或 ETag 做樂觀鎖。衝突回 409 或預條件失敗 412 依契約選定。']],
`POST /assignments/{id}/submissions\nAuth：有效 session、已選課、本人\nRequest：{content, version}\nSuccess：201 + submission\nErrors：401/403/404/409/422\nIdempotency-Key：依使用者與操作限定範圍\nGET 列表：固定排序、limit 上限、cursor`,
['定義 404 是否隱藏存在性，整個系統保持一致。','idempotency key 需要 DB 儲存與原子約束，只有標頭不會自動生效。','同一 key 不同 body 應拒絕或按已定義規則處理。'],
'寫出 Course、Assignment、Submission 的 6 個 API 契約。選一個建立操作加入重複請求規則，選一個更新加入版本衝突規則。',
`方法與路徑：\n輸入與輸出：\n身分與資源權限：\n錯誤：\n重複與衝突：\n驗收案例：`,
['對每個介面寫至少一個越權案例。','與 Week 10 的唯一約束對齊，不以 API 規格宣稱 DB 未保護的事情。'],
`建立繳交以 (assignment_id, student_id) 的唯一約束保護。\n重複請求可回原結果，或明確拒絕；選一套一致方案。\n更新使用 expected_version；DB 條件 UPDATE 失敗則衝突。\n驗收：兩個同時請求不丟失修改，不重複建立。`,
[q('只傳 Idempotency-Key 就保證不重複嗎？',['是','否，伺服器需實作儲存與約束','只適用 GET'],1,'標頭沒有自動副作用，需可靠的去重邏輯。'),q('版本號可用來？',['防止覆寫他人的並行更新','提高 CSS 效能','取代登入'],0,'樂觀鎖檢查資料是否自上次讀取後被修改。')],
[['OpenAPI 規格','https://spec.openapis.org/oas/latest.html'],['MDN：條件請求',MDN+'Web/HTTP/Conditional_requests']]);
lesson(27,
[['ADR 儲存決定的背景','一份 ADR 至少有狀態、context、選項、decision 與 consequences。它不是產品廣告，需說明採用方案付出的代價。記錄當時的資訊，讓未來的人知道不是隨意選擇。'],['可以改變但保留歷史','新證據出現時用新的 ADR 取代舊決定，標示 superseded，而非重寫成從未選錯。避免只寫「比較好」；把團隊能力、資料形狀、成本與維運需求連到決定。']],
`ADR-001：使用 PostgreSQL\nStatus：Accepted\nContext：課程、選課與繳交有關聯與唯一約束，兩人維運。\nOptions：PostgreSQL、檔案資料庫。\nDecision：選 PostgreSQL。\nConsequences：有交易與約束；仍需 migration、備份與索引維護。\nRevisit：資料需求或運維限制改變時重評。`,
['理由連回需求，不以「大家都用」當證據。','被拒方案說明何處不符當前情境，不說它永遠不好。','每份 ADR 解決一個範圍清楚的決定。'],
'寫 5 份 ADR：DB、登入、附件、單體/服務拆分、部署。每份列至少兩選項、一個代價與重新評估條件。',
`Title：\nStatus：\nContext：\nOptions：\nDecision：\nConsequences：\nRevisit：`,
['先寫限制，選項才有比較標準。','月費、維運時間與可恢復性都可作比較，但價格要查當下來源。'],
`單體 ADR：初期團隊小、模組可共用交易，先做模組化單體。\n代價：部署耦合、擴充套件粒度較粗。\n重新評估：特定模組負載/發布節奏/團隊邊界形成獨立需求。\n不以未驗證的「微服務一定更快」當理由。`,
[q('ADR 應記錄代價嗎？',['應該','不用','只記結論'],0,'取捨是決策可評估的核心。'),q('新決定取代舊決定時？',['刪除舊歷史','保留並標示被取代','裝作從未改過'],1,'歷史說明當時背景，有助於理解系統演進。')],
[['ADR：原始提案','https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions']]);
lesson(28,
[['先找慢在哪裡','快取把昂貴的結果暫存，命中時減少重算或資料庫查詢。先量測延遲與查詢次數，再選可接受短暫舊資料的讀取。成績、付款與權限等資料的過期代價高，不能為了加速忽略一致性。'],['TTL 與失效策略','cache-aside 先查快取，未命中才查 DB 並填入。TTL 限制儲存時間，但不保證立即更新。修改 DB 後刪除相關快取，仍可能有並行競爭；鍵需要包含使用者範圍、引數或版本，避免把私人結果給其他人。']],
`def get_public_courses():\n    cached = cache.get("public_courses:v1")\n    if cached is not None:\n        return decode(cached)\n    rows = database.list_public_courses()\n    cache.set("public_courses:v1", encode(rows), ttl=60)\n    return rows`,
['cache、encode 與 database 是抽象介面；依所選函式庫實作。','此處只快取公開清單，60 秒為練習假設。','快取失敗可回源，但要避免流量突然全部壓到 DB。'],
'對公開課程列表實作 cache-aside。比較冷查詢、命中、更新後與 Redis 停止四種情況，寫明可容許過期時間。',
`查詢成本：\n快取鍵與 TTL：\n失效策略：\n四種情況的量測：\n私人資料隔離：`,
['記錄平均與 p95，不只挑最快一次。','課程發布/隱藏會影響清單，列出全部使快取失效的操作。'],
`鍵 public_courses:v1；發布或隱藏後刪鍵。\nTTL 僅限制陳舊時間；針對同時寫入/回填設計版本或其他策略。\nRedis 失敗回源並監控 DB 壓力；量測前後相同負載。`,
[q('TTL 保證修改後立刻看到新值嗎？',['保證','不保證','只對私人資料保證'],1,'TTL 是期限，不是即時失效通知。'),q('私人查詢快取鍵應？',['所有人共用同一鍵','包含適當身分與資源範圍','只放 CSS 類名'],1,'鍵與授權需避免不同使用者結果混用。')],
[['Redis：快取模式','https://redis.io/docs/latest/develop/use/patterns/']]);
lesson(29,
[['回應與背景工作分開','寄信、縮圖等工作可排入 queue，再由 worker 處理。202 Accepted 表示已接受處理，不表示信已寄出。需儲存 job 狀態並提供查詢。單純 process 內的 background task 在重啟時可能遺失，不能當成持久 queue。'],['重試可能重複執行','很多 queue 提供至少一次送達，worker 可能拿到重複訊息。副作用需要冪等鍵或 provider 的去重支援。寫 DB 後再入隊可能只完成一半，可用 transactional outbox 把待發事件與業務記錄一起提交。']],
`transaction:\n  INSERT submission\n  INSERT outbox(event_id, type="submission_received", status="pending")\ncommit\n\nrelay: read pending → publish to queue → mark published\nworker: consume → send email → record result`,
['outbox 保護業務寫入與待發事件一起儲存。','relay 在 publish 後、標記前當機仍可能重送，worker 需處理重複。','對外寄信無法靠本機 DB 交易自動保證完全一次，需評估供應商能力。'],
'做寄信 job 的狀態流程，模擬 provider 超時與 worker 重啟。設最大重試、退避、失敗清單與人工重送，說明重複信如何減少。',
`Job 狀態：\n事件 ID 與去重：\n最大重試與退避：\n中途當機的視窗：\n失敗查詢與重送：`,
['即使先查「寄過了嗎」，查詢與寄信之間仍有競爭或當機視窗。','記錄 queued/running/succeeded/failed，不用單一 success boolean。'],
`job_id 與 event_id 穩定，限次重試並加延遲。\nprovider 支援冪等鍵時傳入 event_id；不支援則記錄重複風險。\n最後失敗進待人工處理清單，不能無限重試。\nAPI 回應 accepted 與查詢 URL，與寄信成功分開。`,
[q('202 表示？',['背景工作已完成','請求已接受，尚可能未完成','一定失敗'],1,'接受與成功完成是不同狀態。'),q('outbox 是否自動消除所有重複寄信？',['是','否，仍需處理重送與外部副作用','不需要 worker'],1,'交付和外部處理間仍存在重複執行視窗。')],
[['AWS：Transactional outbox','https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html']]);
lesson(30,
[['擴充先從負載估算','垂直擴充增加一臺機器的能力；水平擴充增加執行個體。負載平衡將請求分配出去，仍需健康檢查與超時。每個 worker 的本機記憶體不共享，登入 session、上傳檔案和工作狀態不能假設一直落在同一臺。'],['資料庫與成本','讀取複本可能有延遲，剛寫入的內容未必立刻查到。連線池總數需隨 API 複本數一起估算。十萬帳號只是規模的一部分，應由尖峰 RPS、附件流量、CPU/DB 指標找瓶頸，並比較月費與維運負擔。']],
`假設（練習用，需量測）：\n同時活躍 500 人 × 每人每分鐘 6 次請求 ≈ 50 RPS\nAPI 3 個複本 × 每個 pool 10 個連線 = 至多 30 個連線\n附件：200 次/日 × 10 MB ≈ 2 GB/日（未含下載）\n寫入走主 DB；容許延遲的讀取才考慮複本`,
['估算假設要可調整，不把示例數字當成實際平臺需求。','驗證負載是否均勻；尖峰可能遠高於平均。','比較 CPU、DB、網路與外部服務的限制，再提出擴充。'],
'替十萬會員平臺提出單機與三個 API 複本兩方案。列負載假設、session/附件儲存、DB 連線上限、瓶頸和可量測的擴充門檻。',
`會員/活躍/並行：\nRPS 與附件流量：\nSession 與檔案：\nDB 連線：\n量測指標與擴充門檻：\n成本專案：`,
['不要把多臺 API 說成 DB 自動變快。','月費需查實際供應商價格，教材僅列計算專案。'],
`先量測單機能力，保留預算和容量餘裕。\n水平擴充使用共享 session 或可驗證身分方案，共享物件儲存。\n總 pool 不超過 DB 容量；檢查慢查詢與鎖等待。\n成本包含運算、儲存、流量、備份、日誌與維運時間。`,
[q('增加 API 複本能保證 DB 更快嗎？',['能','不能，甚至可能增加壓力','會自動建立索引'],1,'API 擴充可能增加 DB 並行與連線數。'),q('讀取複本可能有？',['複製延遲','永遠零延遲','自動取代備份'],0,'非同步複製需要時間，讀一致性要依用途設計。')],
[['PostgreSQL：熱備援',PG+'hot-standby.html']]);
lesson(31,
[['輸入與權限是不同風險','SQL injection 把輸入混進 SQL，使用引數繫結降低風險。XSS 把不可信內容當可執行 HTML/JS。IDOR/BOLA 是隻換資源 ID 就讀寫他人資料；UUID 不是授權。先在自己的隔離練習環境測試。'],['CSRF 與上傳','Cookie 自動攜帶的身分讓跨站修改操作需 CSRF 防護；CORS 不等於完整 CSRF 防護。上傳需限制大小、允許型別、檢查內容、隨機儲存鍵、隔離與存取權。副檔名和 MIME 都不能單獨證明安全。']],
`# 權限測試情境\n學生 A 登入，讀取 A 的 submission：允許\n使用相同 session，把 ID 換成 B 的 submission：拒絕\n上傳檔名 ../../secret：不可作為儲存路徑\n前端顯示 <script>：當作文字，不執行`,
['對 B 的拒絕還要確認資料沒有洩漏或變動。','用服務端產生 storage key，原檔名只作受控顯示資料。','不要把惡意檔案測試送到正式平臺。'],
'在自己的測試環境做四項安全驗證：引數化 SQL、跨使用者資源、文字顯示、附件大小。記錄預期、實際結果與修正。',
`測試環境：\nSQL 查詢方式：\n跨使用者資源：\nXSS 顯示：\n附件大小與型別：\n修正與重測：`,
['以兩個假學生資料測試，避免接觸真實個資。','大小限制應在可信服務端實施，不只在 input 上檢查。'],
`SQL 值使用驅動引數；學生只讀自己的資源。\n不可信文字用 textContent，HTML 如需允許則專門清理。\n上傳採允許清單、大小限制、內容檢查與私有儲存。\n測試拒絕後無副作用，所有結果可重複。`,
[q('把資源 ID 換成 UUID 就解決越權嗎？',['會','不會，仍需資源權限檢查','只對學生有效'],1,'難猜 ID 不等於有權讀取。'),q('檔案安全只查副檔名夠嗎？',['夠','不夠','改名即可'],1,'名稱可偽造，需要多層驗證與隔離。')],
[['OWASP：授權',OWASP+'Authorization_Cheat_Sheet.html'],['OWASP：上傳',OWASP+'File_Upload_Cheat_Sheet.html']]);
lesson(32,
[['用資料流找信任邊界','Threat model 先列資產、入口、資料流與信任邊界，再考慮攻擊者能控制什麼。不是隻列攻擊名詞。每項威脅都連到影響、已有防護、偵測與恢復，尚未處理的列成風險決策。'],['AI 輸入也是不可信資料','檔案、網站與使用者輸入可能含 prompt injection。不能因模型說「應當允許」就繞過權限。工具呼叫需服務端驗證、限制操作與資料範圍；輸出也需確認。對高影響操作保留明確的控制邊界。']],
`資產：私人作業與評分\n入口：附件上傳、AI 問題顧問\n威脅：附件文字誘導模型讀取其他學生作業\n預防：模型不持有跨使用者資料；工具逐次授權\n偵測：拒絕事件與異常讀取\n恢復：撤銷存取、追查外洩範圍、修正邊界`,
['記錄攻擊路徑，而非只寫 prompt injection 四個字。','system prompt 不是完整的權限執行邊界。','風險評分是團隊決策輔助，不是精確機率。'],
'替登入、附件、AI 顧問各列 3 個威脅。每個附資產、路徑、impact、控制、偵測與恢復，標記殘餘風險。',
`資產與資料流：\n威脅與路徑：\n影響：\n預防：\n偵測：\n恢復：\n殘餘風險與負責人：`,
['工具能做什麼，比模型承諾什麼更重要。','至少包含其他使用者資料、秘密外洩及重複操作。'],
`登入：猜密碼→限速/適當驗證/告警；不洩漏是否存在。\n附件：惡意內容→限制/隔離/受控存取。\nAI：越權工具呼叫→服務端範圍檢查與最小權限。\n控制失敗後的復原與責任人寫入 runbook。`,
[q('system prompt 能取代服務端授權嗎？',['不能','能，只要寫得強硬','只對 PDF 能'],0,'模型內容不能成為可信的授權執行機制。'),q('威脅模型需涵蓋？',['只有攻擊名稱','資產、路徑、控制與恢復','只有畫面'],1,'威脅需與實際資料流和可行控制連結。')],
[['OWASP：威脅建模',OWASP+'Threat_Modeling_Cheat_Sheet.html'],['OWASP：LLM Prompt Injection',OWASP+'LLM_Prompt_Injection_Prevention_Cheat_Sheet.html']]);
lesson(33,
[['失敗要定義服務行為','DB、郵件、物件儲存與 AI 都可能失敗。timeout 限制等待，retry 只對合適錯誤、冪等操作、限次退避使用。快速重試會放大故障。AI 不可用時可儲存草稿並允許人工流程，不能把失敗回答當作完成。'],['恢復要實際演練','RPO 是可容許資料遺失視窗，RTO 是恢復所需時間目標。備份存在不代表能還原；在隔離環境執行 restore 並檢查資料。程式 rollback 與 DB migration rollback 是不同問題，需向後相容與恢復方案。']],
`依賴 | 失敗行為 | 偵測 | 恢復\nDB | 拒絕寫入、回可重試錯誤 | 錯誤率/健康 | 還原/切換\nEmail | 儲存 job、稍後重試 | 積壓/失敗數 | 重送\nAI | 儲存問題、顯示暫不可用 | timeout | 人工或重試\nStorage | 保留 pending 狀態 | 失敗數 | 補傳/清理`,
['不把 API 的 success 回給尚未完成的資料寫入。','healthcheck 不暴露秘密；readiness 與 liveness 責任分開。','RTO/RPO 是需求目標，實際達成要靠演練量測。'],
'對自己的練習 DB 做 backup，在新的隔離 DB restore，核對行數與主要內容。模擬一次依賴超時並記錄退避。寫部署失敗恢復步驟。',
`備份時間與範圍：\n隔離還原位置：\n資料核對：\n實際恢復耗時：\nRTO/RPO 目標：\n部署回復步驟：`,
['還原前再確認是新練習 DB，避免覆蓋現有資料。','備份檔案可能有私人資料，不上傳 GitHub。'],
`pg_dump → 新建 restore_test → pg_restore。\n檢查表、行數、約束和關鍵資料，記錄時間。\n超時：有限次指數退避；非冪等操作先查狀態或使用去重。\n回滾程式版本前確認其相容新 DB schema。`,
[q('有備份檔代表恢復成功嗎？',['代表','不代表，需還原驗證','只需看大小'],1,'有效恢復包括可讀、可還原與資料核對。'),q('無限快速重試的問題？',['可能放大故障','一定最快恢復','自動保證一致'],0,'重試會增加依賴負載，需限次與退避。')],
[['PostgreSQL：備份',PG+'backup.html'],['Google SRE：過載','https://sre.google/sre-book/handling-overload/']]);
lesson(34,
[['規格給 AI 可驗收的界線','先寫角色、情境、資料模型、API、權限、邊界與驗收。把大需求拆成可獨立檢查的工作。規格不完整時標記未知，不讓 AI 任意決定重要安全或資料規則。'],['規格與結果互相追蹤','每條驗收準則對應測試與實作位置。AI 可以協助解釋、起草與檢查，但你必須審核差異、跑測試並理解行為。從小功能開始，限制允許修改的檔案與範圍，避免順手重寫整個系統。']],
`Feature：本人修改提問草稿\nScope：僅 draft，不改已發布內容\nPermission：有效 session、question.owner_id == user.id\nAPI：PATCH /questions/{id}\nConflict：version 不符拒絕\nAcceptance：本人成功；他人拒絕且資料不變；已發布拒絕\nAllowed files：question service、相關測試`,
['安全要求需有拒絕案例，而不是一句「安全」。','先讀 existing code 和 schema，避免指令與現實衝突。','AI 回報測試透過後仍確認實際輸出與測試覆蓋範圍。'],
'寫一份修改草稿規格，請 AI 只實作此功能。儲存原始規格、diff、測試輸出與驗收表，指出一個 AI 需要澄清的未知。',
`Feature：\nActors：\nRules：\nData/API：\nPermissions：\nFailures：\nAcceptance：\nAllowed changes：`,
['明確寫「不可修改已發布內容」，並測試。','需求變更也要更新規格，不只改 code。'],
`REQ-DRAFT-01 對應成功測試與服務函式。\nREQ-DRAFT-02 對應他人資源拒絕/無副作用。\nREQ-DRAFT-03 對應 published 不可修改。\nversion 衝突的處理需先選定；AI 不可自行放寬。`,
[q('可驗收的 AI 指令需要？',['只有「做得好」','規則、範圍與可重複驗證案例','只指定框架'],1,'驗收界線能讓產出被檢驗。'),q('AI 回報完成後應？',['直接相信','檢查 diff、測試與實際行為','刪掉規格'],1,'你仍負責確認產出符合需求。')],
[['GitHub：負責任使用 Copilot','https://docs.github.com/en/copilot/responsible-use-of-github-copilot-features']]);
lesson(35,
[['Review 要找可證明的問題','檢查身分、資源範圍、資料完整性、並行、錯誤處理與維運。第二個 AI session 可提供另一視角，不保證獨立或正確。每項發現需位置、觸發條件、影響與修正，不把猜測當成已確認缺陷。'],['用迴歸測試驗證修正','人工重現或寫最小失敗測試，修正後同測試透過。對「效能不好」等說法先量測。評審也需檢查測試是否真正覆蓋風險，避免測試 mock 掉了被懷疑的部分。']],
`Finding：TA 可批改未指派課程\nTrigger：有效 TA session + 其他課程 submission ID\nEvidence：403 預期卻回 200，DB 成績被改\nFix：服務端查課程指派\nRegression：未指派拒絕且 DB 不變；指派者成功`,
['同時證明錯誤 status 與資料副作用。','不能只修前端按鈕，也不能只改測試期待為 200。','評估 AI finding 是否能重現，再決定嚴重程度。'],
'請 AI review 你的一個小模組，最多挑 5 項發現。把每項分類為已重現、誤報或待驗證；對兩個有效問題補回歸測試。',
`Finding：\n位置：\n觸發：\n證據：\n影響：\n修正：\n迴歸：\n未確認事項：`,
['沒有真問題時不要捏造兩項；可先在自己的練習版本刻意加入缺陷。','優先用越權或並行測試，避免只測 2+2。'],
`已確認項提供失敗與修復後輸出。\n誤報寫明實際約束/路徑如何阻止，附證據。\n待驗證列需要環境或量測，不寫成確定結論。\n最終報告對照規格，說明測試邊界。`,
[q('第二個 AI review 是否保證沒有錯？',['保證','不保證，仍需驗證','只要換名字就保證'],1,'模型意見不是證據，需看實際行為。'),q('發現權限漏洞的合理修正？',['隱藏按鈕','服務端檢查並補回歸測試','修改期待為成功'],1,'可信邊界必須執行規則。')],
[['Google：Code Review','https://google.github.io/eng-practices/review/reviewer/']]);
lesson(36,
[['完整交付包含維運','最終專案是一套能說明、實作、驗收與恢復的學習平臺。連線需求、C4、ER、RBAC、API、威脅、故障、部署、監控與成本。圖與程式碼不一致時記錄並修正，不用檔案數量代替內容質量。'],['指揮 Agent 與責任歸屬','以模組邊界分工，先訂共享 schema/API，再安排實現與測試。每次合併檢查差異、權限與結果，避免多個 agent 同時改同檔案而失去控制。角色分配不是安全保證，你仍需驗收。36 周是練習安排，不保證自動取得架構師職務。']],
`架構包：\n01 requirements；02 context；03 containers；04 ER\n05 permissions；06 API；07 threat；08 failure\n09 deployment/monitoring/cost；10 ADR\n交付追蹤：REQ → 設計 → 實作 → 測試 → 運維\n釋出：檢查 → 暫存演練 → 正式部署 → 觀察 → 可回退`,
['先用獨立 Mini LMS，避免在正式 RISE 平臺練習故障。','監控需含錯誤率、延遲、任務積壓、容量與實際使用者流程。','成本使用當下價格與負載假設估算，明確資料來源與誤差。'],
'完成 Mini LMS 架構包與一個端到端模組。用 60 分鐘說明需求到運維，並演示越權拒絕、依賴失敗、恢復與進度追蹤。交付十份 ADR 與成本表。',
`系統範圍：\n架構檔案索引：\n一個端到端模組：\n需求→測試對照：\n故障與恢復演示：\n監控與成本：\n未完成與後續：`,
['任選作業提交、提問草稿等小模組，不需要一次做完整 RISE。','驗收報告須明確哪些自動測、哪些人工測、哪些尚未驗證。'],
`可交付標準：每個需求有證據，權限與資源範圍一致。\n附件/郵件/AI 故障有明確行為與恢復流程。\n監控有目標與告警責任；成本可從假設重新計算。\nAgent 修改經 review 與合併驗證；所有限制誠實列出。`,
[q('最終能力如何衡量？',['用了多少框架','能解釋決策、驗證行為並恢復故障','只有 UI 漂亮'],1,'架構工作連線需求、約束與可執行證據。'),q('Agent 分工後誰承擔驗收責任？',['架構負責人仍需驗收','不需要任何人','只要 agents 互相說正確'],0,'分工不移除系統設計與驗收責任。')],
[['C4：檢查清單','https://c4model.com/diagrams/checklist'],['Google SRE：監控','https://sre.google/sre-book/monitoring-distributed-systems/']]);
